            if value <= max_group and idx < min_index[value]:
                min_index[value] = idx

        # best[g] = smallest element index that divides g.
        best = [inf] * (max_group + 1)

        for value in range(1, max_group + 1):
            idx = min_index[value]
            if idx != inf:
